def stable_group_pairs(pairs):
    groups = []
    seen = set()
    for key, value in pairs:
        if key not in seen:
            seen.add(key)
            groups.append([key, []])
        for pair in groups:
            if pair[0] == key:
                pair[1].append(value)
                break
    return groups
